<?php
declare(strict_types=1);namespace Liberu\Accounting\ProductAndServiceItemsApi\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Liberu\Accounting\ProductAndServiceItems\Actions\SaveAccountingItem;use Liberu\Accounting\ProductAndServiceItems\Models\AccountingItem;use Liberu\Accounting\ProductAndServiceItems\Queries\FindAccountingItems;final class ProductAndServiceItemsController extends Controller{public function index(Request $request,FindAccountingItems $query):mixed{return $query->search($request->string('search')->toString())->paginate(min((int)$request->input('per_page',25),100));}public function store(Request $request,SaveAccountingItem $action):AccountingItem{return $action->handle($request->validate(['team_id'=>'nullable|integer','code'=>'required|string|max:100','name'=>'required|string|max:255','kind'=>'required|in:item,service','purchase_description'=>'nullable|string','sales_description'=>'nullable|string','sales_account_ref'=>'nullable|string','purchase_account_ref'=>'nullable|string','tax_default_ref'=>'nullable|string','unit'=>'nullable|string|max:32','purchase_price'=>'nullable|numeric|min:0','sales_price'=>'nullable|numeric|min:0','currency'=>'required|string|size:3','status'=>'nullable|in:active,inactive,archived','ecommerce_refs'=>'nullable|array','metadata'=>'nullable|array']));}public function show(AccountingItem $accountingItem):AccountingItem{return $accountingItem;}}
